def get_divisors(n):
    divs = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

results = []

# Test values of n from 2 to 100
for n in range(2, 101):
    divs = get_divisors(n)
    tau_n = len(divs)

    # Check if n has at least 5 positive divisors
    if tau_n >= 5:
        # a, b, c are the 2nd, 3rd, and 5th smallest divisors
        # Smallest divisor is divs[0] = 1
        a = divs[1] # 2nd smallest
        b = divs[2] # 3rd smallest
        c = divs[4] # 5th smallest

        # Verify the condition: ab + ac + bc = n
        condition_met = (a * b + a * c + b * c) == n

        if condition_met:
            results.append((n, tau_n))

print("N satisfying the condition and tau(N):")
if results:
    for n, tau in results:
        print(f"n = {n}, tau(n) = {tau}")
else:
    print("No such values found in the range [2, 100].")

